"""
Generate the scraper table of README.md (and of its translations in docs/README.<language>.md) and llms.txt from the
scraper folders, so none of them is edited by hand.

    python .github/scripts/docs.py                        # rewrite the README tables and llms.txt
    python .github/scripts/docs.py --check                # exit 1 when one of them is out of date
    python .github/scripts/docs.py --status status.json   # also order the README rows by the last nightly run

Where each part comes from:
- one README row and one llms.txt entry for every <name>-scraper folder; llms.txt is sorted by website name, the
  README rows keep the order they have (new folders go last) unless --status is given the status.json that
  .github/scripts/ci_status.py writes to the ci-status branch: then they are ordered by the last nightly run,
  passing scrapers first, then partly passing, failing and not run ones (the nightly's status job does this);
- .github/scrapers.json (optional for each folder): website name, scrape guides (link and title), sample dataset
  labels;
- without an entry there: the website name of the folder README title ("# Airbnb.com Scraper"), the first
  scrapfly.io/blog article linked in that README, and a label made from the file name ("hotel_reviews.json" ->
  "Hotel reviews");
- sample datasets: every results/*.json file; functions (llms.txt): the scrape_* functions of the scraper code with
  the first paragraph of their docstring;
- status: the nightly badge that .github/scripts/ci_status.py writes to the ci-status branch, linked to the
  scraper's page of the last run there (each test with its job log).

Standard library only.
"""
import argparse
import ast
import json
import re
import sys
import warnings
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
REPO = "scrapfly/scrapfly-scrapers"
EXTRA = ROOT / ".github" / "scrapers.json"
GUIDE_LINK = re.compile(r"https://scrapfly\.io/blog/[^\s)\"'>]+")
# translated READMEs: the same table, links one folder up, column headers in that language
TRANSLATIONS = {
    "zh-CN": ("网站", "指南", "示例数据", "状态"),
    "ja": ("サイト", "ガイド", "サンプルデータ", "ステータス"),
    "es": ("Dominio", "Guía", "Datos de ejemplo", "Estado"),
    "ru": ("Сайт", "Руководство", "Примеры данных", "Статус"),
}
HEADERS = ("Domain", "Guide", "Sample Datasets", "Status")
TABLE_NOTE = (
    "<!-- This table is generated by .github/scripts/docs.py from the scraper folders and .github/scrapers.json: "
    "change those and run the script instead of editing it. -->"
)

LLMS_HEADER = """\
# Scrapfly Scrapers

> Example web scrapers for {count} popular websites (Amazon, eBay, Zillow, Booking.com and more), written in \
Python with the Scrapfly SDK, one folder per website. Each scraper is a short module of async functions that \
return JSON-ready data, with an example script (`run.py`), live tests (`test.py`) and sample output (`results/`).

These scrapers are educational examples that accompany the Scrapfly scrape guides: copy one and adapt it, they are not \
an installable library. Every request goes through the Scrapfly API, so a Scrapfly API key is needed \
(https://scrapfly.io/register, then https://scrapfly.io/dashboard).

## When an agent should use this repository

- The user wants data from one of the websites listed under "Scrapers": start from that folder instead of writing a \
scraper from scratch.
- The user wants to scrape a similar website: copy the scraper of the closest website (same kind of pages: search \
results, product, property, profile, reviews) and adapt its URLs, parsing and tests.
- The user wants to learn how a website is scraped: most folders link a step-by-step guide.

## Use a scraper

```bash
git clone https://github.com/scrapfly/scrapfly-scrapers.git
cd scrapfly-scrapers/amazon-scraper        # any <name>-scraper folder
export SCRAPFLY_KEY="your API key"         # from https://scrapfly.io/dashboard
poetry install --no-root                   # Python 3.10+
poetry run python run.py                   # example scrape, writes results/*.json
poetry run pytest test.py -k test_search   # live tests, one test at a time with -k
```

From Python, inside the scraper folder:

```python
import asyncio
import amazon  # the module has the name of the folder without "-scraper"

results = asyncio.run(amazon.scrape_search("https://www.amazon.com/s?k=kindle", max_pages=1))
```

- The module reads `SCRAPFLY_KEY` from the environment when it is imported.
- In most modules `BASE_CONFIG` holds the Scrapfly settings sent with every request (anti-bot bypass, country, \
...); change an entry there (for example `BASE_CONFIG["cache"] = True`) rather than every request.
- The functions return plain dicts and lists; `results/` holds the output `run.py` produced with them.
- `run.py` and the tests scrape the live websites, so they use Scrapfly credits and fail when a website changes.

## Scrapers

Each entry: the folder, its scrape guide, its sample output and its public functions (`async`, run them with \
`asyncio.run` or `await`).

"""

LLMS_FOOTER = """
## Write a new scraper

Follow the layout and style of the existing folders (the maintainers' rules):

1. Create a `<name>-scraper/` folder with:
   - `<name>.py`: all the scraper code;
   - `run.py`: runs the scraper on example URLs and saves the output to `results/*.json`;
   - `test.py`: pytest tests that check live output against a [cerberus](https://docs.python-cerberus.org/) schema;
   - `results/`: the sample output written by `run.py`;
   - `README.md`: a copy of another scraper's README with the website name changed;
   - `pyproject.toml`: a Poetry project like the other folders (no `poetry.lock`, so users get the latest SDK).
2. Code:
   - top-level `async def scrape_*()` functions such as `scrape_search(url, max_pages=...)` and \
`scrape_products(urls)`, with small synchronous `parse_*()` helpers;
   - one module-level `SCRAPFLY = ScrapflyClient(key=os.environ["SCRAPFLY_KEY"])` and a `BASE_CONFIG` dict spread \
into every `ScrapeConfig(url, **BASE_CONFIG)`;
   - several URLs at once with `SCRAPFLY.concurrent_scrape()`, with the concurrency limit set to automatic;
   - prefer the JSON data hidden in the page over HTML selectors, keep results flat, use type hints and short \
comments, keep it simple: the code is for learning;
   - inputs are full URLs rather than values the scraper turns into URLs; use small defaults (pages, items).
3. Tests: one schema per result type plus length checks (for example a search returns at least N items); mark them \
with `@pytest.mark.asyncio` and `@pytest.mark.flaky(reruns=3, reruns_delay=30)`, with `pytest-rerunfailures` in \
the dev dependencies.
4. Nothing to add to the CI: the nightly run tests every `test_*` function of every `test.py` (tests that must not \
run are listed in `.github/test_matrix_exclude.txt`).
5. Run `python .github/scripts/docs.py` to add the scraper to the README table and to this file; put its website \
name, guide and sample dataset labels in `.github/scrapers.json` when the defaults are not right.

To start, copy the folder of a listed scraper for a similar website and keep its structure.

## Links

- Scrapfly for agents: https://scrapfly.io/llms.txt (every documentation page: https://scrapfly.io/docs/llms.txt)
- Scrapfly Python SDK: https://github.com/scrapfly/python-scrapfly
- Scrape guides: https://scrapfly.io/blog/tag/scrapeguide/
- Repository: https://github.com/scrapfly/scrapfly-scrapers
"""


def module_file(folder: Path) -> Path:
    """the scraper code: <name>.py, or the only other .py file (realestatecom-scraper has realestate.py)"""
    expected = folder / (folder.name.removesuffix("-scraper").replace("-", "_") + ".py")
    if expected.exists():
        return expected
    others = [p for p in folder.glob("*.py") if p.name not in ("run.py", "test.py")]
    return others[0]


def signature(node: ast.FunctionDef) -> str:
    """name(arg, arg=default, ...) without type hints"""
    args = node.args
    positional = args.posonlyargs + args.args
    defaults = [None] * (len(positional) - len(args.defaults)) + list(args.defaults)
    parts = [a.arg if d is None else f"{a.arg}={ast.unparse(d)}" for a, d in zip(positional, defaults)]
    parts += [a.arg if d is None else f"{a.arg}={ast.unparse(d)}" for a, d in zip(args.kwonlyargs, args.kw_defaults)]
    return f"{node.name}({', '.join(parts)})"


def scrape_functions(path: Path) -> list:
    """(signature, first docstring paragraph) of every top-level scrape_* function (async, except in airfrance)"""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", SyntaxWarning)  # old escape sequences in some scrapers' strings
        tree = ast.parse(path.read_text(encoding="utf-8"))
    functions = []
    for node in tree.body:
        if isinstance(node, (ast.AsyncFunctionDef, ast.FunctionDef)) and node.name.startswith("scrape"):
            doc = " ".join((ast.get_docstring(node) or "").split("\n\n")[0].split())
            if isinstance(node, ast.FunctionDef):
                doc = "(not async) " + doc
            functions.append((signature(node), doc.strip()))
    return functions


def readme_text(folder: Path) -> str:
    readme = folder / "README.md"
    return readme.read_text(encoding="utf-8") if readme.exists() else ""


def site_name(folder: Path) -> str:
    """the website name of the folder README title ("# Airbnb.com Scraper"), else the folder name"""
    lines = readme_text(folder).splitlines()
    name = re.sub(r"^#\s*|\s*scraper\s*$", "", lines[0] if lines else "", flags=re.I).strip()
    return name or folder.name.removesuffix("-scraper")


def readme_guide(folder: Path) -> str:
    """the first scrape guide article linked in the folder README (tag pages list many articles, not a guide)"""
    links = [link for link in GUIDE_LINK.findall(readme_text(folder)) if "/tag/" not in link]
    return links[0] if links else ""


def guide_title(url: str) -> str:
    """a title made from the article address: .../how-to-scrape-zoopla -> How to Scrape Zoopla"""
    words = url.rstrip("/").rsplit("/", 1)[-1].split("-")
    small = {"to", "and", "in", "of", "for", "a", "the", "with", "using"}
    return " ".join(w if w in small else w.capitalize() for w in words).replace("How To", "How to")


def dataset_label(file: str) -> str:
    """a label made from the file name: hotel_reviews.json -> Hotel reviews"""
    words = Path(file).stem.replace("_", " ").replace("-", " ")
    return words[:1].upper() + words[1:]


def scrapers() -> list:
    """everything the README table and llms.txt show about each scraper folder, sorted by website name"""
    extra = json.loads(EXTRA.read_text(encoding="utf-8")) if EXTRA.exists() else {}
    items = []
    for folder in sorted(p for p in ROOT.iterdir() if p.is_dir() and p.name.endswith("-scraper")):
        info = extra.get(folder.name, {})
        guides = info.get("guides") or ([{"url": readme_guide(folder)}] if readme_guide(folder) else [])
        labels = info.get("datasets", {})
        files = sorted(p.name for p in folder.glob("results/*.json"))
        # labelled files first, in the order of scrapers.json, then the others
        files = [f for f in labels if f in files] + [f for f in files if f not in labels]
        items.append(
            {
                "dir": folder.name,
                "name": info.get("name") or site_name(folder),
                "guides": [{"url": g["url"], "title": g.get("title") or guide_title(g["url"])} for g in guides],
                "datasets": [(f, labels.get(f) or dataset_label(f)) for f in files],
                "functions": scrape_functions(module_file(folder)),
            }
        )
    return sorted(items, key=lambda item: item["name"].lower())


def status_rank(results: list) -> int:
    """README order from the conclusions of a scraper's test jobs, like the badge of ci_status.py: every test passed,
    some passed, none passed, not run"""
    if not results:
        return 3
    passed = sum(1 for r in results if r == "success")
    return 0 if passed == len(results) else 1 if passed else 2


def readme_order(items: list, readme: str, status_file: Path = None) -> list:
    """the README rows: by the results of the last nightly run when its status.json is given (passing scrapers
    first, then partly passing, failing and not run), else in the order they already have; scrapers without a row
    come last, by website name"""
    if status_file:
        results = {}
        for job in json.loads(status_file.read_text(encoding="utf-8"))["tests"]:
            results.setdefault(job["dir"], []).append(job["conclusion"])
        return sorted(items, key=lambda s: (status_rank(results.get(s["dir"], [])), s["name"].lower()))
    start, end = table_span(readme)
    position = {d: i for i, d in enumerate(re.findall(r'<td><a href="\./([^/"]+)/">', readme[start:end]))}
    return sorted(items, key=lambda s: (position.get(s["dir"], len(position)), s["name"].lower()))


def readme_table(items: list, badge_repo: str, prefix: str = "./", headers: tuple = HEADERS) -> str:
    """the scraper table; prefix is the path from the README to the repository root ("./" or "../")"""
    rows = []
    for s in items:
        guide = " - ".join(f'<a href="{g["url"]}">{g["title"]}</a>' for g in s["guides"]) or "-"
        datasets = "\n".join(
            f'        <li><a href="{prefix}{s["dir"]}/results/{file}">{label}</a></li>' for file, label in s["datasets"]
        )
        badge = f"https://github.com/{badge_repo}/raw/ci-status/badges/{s['dir']}.svg"
        # the badge links to the scraper's page of the last run (each test with its job log), also on ci-status
        page = f"https://github.com/{badge_repo}/blob/ci-status/status/{s['dir']}.md"
        rows.append(
            "  <tr>\n"
            f'    <td><a href="{prefix}{s["dir"]}/">{s["name"]}</a></td>\n'
            f"    <td>{guide}</td>\n"
            f"    <td>\n    <ul>\n{datasets}\n    </ul>\n    </td>\n"
            f'    <td><a href="{page}"><img src="{badge}" alt="{s["dir"]}-status"></a></td>\n'
            "  </tr>\n"
        )
    header = "  <tr>\n" + "".join(f"    <td><strong>{h}</strong></td>\n" for h in headers) + "  </tr>\n"
    return f"{TABLE_NOTE}\n<table>\n\n{header}\n" + "\n".join(rows) + "\n</table>"


def table_span(readme: str) -> tuple:
    """where the generated table (or the first table under "List of Scrapers") starts and ends in the README"""
    start = readme.find(TABLE_NOTE)
    if start < 0:
        start = readme.find("<table>", readme.find("## List of Scrapers"))
    end = readme.find("</table>", start) + len("</table>")
    if start < 0 or end < len("</table>"):
        sys.exit("docs.py: no scraper table found in README.md")
    return start, end


def replace_table(readme: str, table: str) -> str:
    """put the table in place of the current one"""
    start, end = table_span(readme)
    return readme[:start] + table + readme[end:]


def llms_txt(items: list) -> str:
    entries = []
    for s in items:
        details = [f"[code](https://github.com/{REPO}/tree/main/{s['dir']})"]
        if s["guides"]:
            details.append("guide: " + ", ".join(f"[{g['title']}]({g['url']})" for g in s["guides"]))
        samples = [
            f"[{label}](https://github.com/{REPO}/blob/main/{s['dir']}/results/{f})" for f, label in s["datasets"]
        ]
        if samples:
            details.append("sample output: " + ", ".join(samples))
        lines = [f"- **{s['name']}** (`{s['dir']}/`): " + " | ".join(details)]
        lines += [f"  - `{sig}`" + (f": {doc}" if doc else "") for sig, doc in s["functions"]]
        entries.append("\n".join(lines))
    return LLMS_HEADER.format(count=len(items)) + "\n".join(entries) + "\n" + LLMS_FOOTER


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true", help="exit 1 when a README table or llms.txt is out of date")
    parser.add_argument("--badge-repo", default=REPO, help="repository of the ci-status badges (for test copies)")
    parser.add_argument(
        "--status", type=Path, help="status.json of the ci-status branch: order the README rows by that nightly run"
    )
    args = parser.parse_args()
    items = scrapers()
    readme_path, llms_path = ROOT / "README.md", ROOT / "llms.txt"
    readme = readme_path.read_text(encoding="utf-8")
    rows = readme_order(items, readme, args.status)
    outputs = {readme_path: replace_table(readme, readme_table(rows, args.badge_repo)), llms_path: llms_txt(items)}
    for language, headers in TRANSLATIONS.items():  # same rows in the same order as README.md
        path = ROOT / "docs" / f"README.{language}.md"
        if path.exists():
            text = path.read_text(encoding="utf-8")
            outputs[path] = replace_table(text, readme_table(rows, args.badge_repo, "../", headers))
    stale = [
        str(p.relative_to(ROOT))
        for p, text in outputs.items()
        if not p.exists() or p.read_text(encoding="utf-8") != text
    ]
    if args.check:
        if stale:
            sys.exit(f"out of date: {', '.join(stale)} - run python .github/scripts/docs.py")
        print("README tables and llms.txt are up to date")
        return
    for path, text in outputs.items():
        path.write_text(text, encoding="utf-8")
    print(f"{len(items)} scrapers; rewrote {', '.join(stale) or 'nothing (already up to date)'}")


if __name__ == "__main__":
    main()
